eps"]={[1]=1,[2]=2,[3]=4,[4]=7,[5]=12,[6]=19,[7]=26},["guard"]={[1]=1,[2]=2,[3]=3,[4]=5,[5]=6,[6]=8,[7]=10}},[93]={["id"]=93,["name"]="葵花寶典",["skill"]=-1,["tier"]=4,["curve"]="early",["baseCost"]=170,["maxRank"]=10,["rankUnit"]="重",["mp"]={[1]=53,[2]=71,[3]=89,[4]=103,[5]=116,[6]=126,[7]=135,[8]=141,[9]=147,[10]=150},["effect"]="疾行：学成后最多增加8点轻功；体质与传承沿现有剧情条件。",["entryMax"]=1,["agility"]={},["throw"]={},["removeAptitude"]=false},[94]={["id"]=94,["name"]="九陰真經",["skill"]=-1,["tier"]=4,["curve"]="late",["baseCost"]=170,["maxRank"]=10,["rankUnit"]="重",["mp"]={[1]=11,[2]=19,[3]=30,[4]=44,[5]=61,[6]=82,[7]=105,[8]=131,[9]=160,[10]=190},["effect"]="精微：外功招式威力最多增加8%；与紫霞同类增威取较强值。",["entryMax"]=1,["agility"]={},["throw"]={},["removeAptitude"]=false},[95]={["id"]=95,["name"]="九陽真經",["skill"]=92,["tier"]=4,["curve"]="late",["baseCost"]=170,["maxRank"]=10,["rankUnit"]="重",["mp"]={[1]=12,[2]=20,[3]=32,[4]=46,[5]=64,[6]=86,[7]=110,[8]=138,[9]=168,[10]=200},["effect"]="护身纯内功，本身不出招。**本门的正业是增伤**：自身各门武功威力最多增加8%，逐重递增。另有两项附带的临敌护体——受敌方武功时防御力最多临时增加4点、抗毒能力最多临时增加30点；连同原有的「所受武功附毒量最多减轻40%」，合起来就是《倚天》回二十三所记的诸毒不侵。三项都只在战斗中生效，不写入人物面板。与太极拳原有节省内力相辅保留；与其他已练内功的同类效果各自生效。本作不再给它招式威力，原招式条目只留作境界记录。",["entryMax"]=1,["agility"]={},["throw"]={},["removeAptitude"]=false,["gates"]={["需内力"]=200},["entryCost"]=75,["passive"]={["defencePerRank"]=0.4,["defenceMax"]=4,["resistPerRank"]=3,["resistMax"]=30,["powerPerRank"]=0.008,["powerMax"]=0.08}}}}